result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/yamlout.py", "content": "#!/usr/bin/env python3
"""yamlout.py -- read JSON on stdin, emit readable YAML on stdout.

Conventions:
  * 2-space indentation, block style for mappings and sequences.
  * Empty containers render as {} / [].
  * Strings are quoted only when necessary:
      - empty string
      - leading or trailing whitespace
      - special characters (control chars, indicator-only prefixes,
        ": ", trailing ":", " #")
      - strings that would otherwise parse as null, booleans, or numbers
    Single quotes are preferred; strings containing control characters
    fall back to double quotes with escapes.

No YAML library is used inside the tool; only the Python standard library.
"""

import json
import re
import sys

INDENT = "  "

# ---------------------------------------------------------------------------
# Value-lookalike detection (mirrors PyYAML's YAML 1.1 implicit resolvers,
# so a plain string like "true" or "0x1F" gets quoted and survives a
# round-trip through any compliant parser).
# ---------------------------------------------------------------------------

_BOOL_RE = re.compile(
    r"^(?:yes|Yes|YES|no|No|NO|true|True|TRUE|false|False|FALSE"
    r"|on|On|ON|off|Off|OFF)$"
)
_NULL_RE = re.compile(r"^(?:~|null|Null|NULL)$")
_INT_RESOLVERS = [
    re.compile(r"^[-+]?[0-9]+$"),
    re.compile(r"^[-+]?0b[0-1_]+$"),
    re.compile(r"^[-+]?0x[0-9a-fA-F_]+$"),
    re.compile(r"^[-+]?0[0-7_]+$"),
    # sexagesimal integers, e.g. 190:20:30
    re.compile(r"^[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+$"),
]
_FLOAT_RESOLVERS = [
    re.compile(r"^[-+]?(?:\.[0-9]+|[0-9]+(?:\.[0-9]*)?)(?:[eE][-+]?[0-9]+)?$"),
    re.compile(r"^[-+]?\.(?:inf|Inf|INF)$"),
    re.compile(r"^\.(?:nan|NaN|NAN)$"),
    # sexagesimal floats, e.g. 190:20:30.15
    re.compile(r"^[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*$"),
]

_ALWAYS_INDICATORS = set("#,]}`%@&*!|>'\"[")


def _looks_like_special_value(s):
    """True if a plain (unquoted) rendering of s would be misparsed."""
    if _NULL_RE.match(s) or _BOOL_RE.match(s):
        return True
    if any(rx.match(s) for rx in _INT_RESOLVERS):
        return True
    if any(rx.match(s) for rx in _FLOAT_RESOLVERS):
        return True
    return False


def _can_be_plain(s):
    """True if s may be emitted without quotes in block context."""
    if s == "" or s != s.strip():
        return False
    first = s[0]
    if first in _ALWAYS_INDICATORS:
        return False
    if first in "-?:" and (len(s) == 1 or s[1] == " "):
        return False
    if ": " in s or s.endswith(":") or " #" in s:
        return False
    # control characters are never allowed in plain/single-quoted scalars
    if any(ord(c) < 0x20 or ord(c) == 0x7F for c in s):
        return False
    if _looks_like_special_value(s):
        return False
    return True


def quote_string(s):
    """Render a Python str as a YAML scalar, quoting only when necessary."""
    if _can_be_plain(s):
        return s
    if any(ord(c) < 0x20 or ord(c) == 0x7F for c in s):
        # needs real escapes -> double-quoted style (json.dumps emits a
        # valid YAML double-quoted scalar for such strings)
        return json.dumps(s, ensure_ascii=False)
    return "'" + s.replace("'", "''") + "'"


# ---------------------------------------------------------------------------
# Scalar rendering for non-string JSON values
# ---------------------------------------------------------------------------


def render_scalar(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, float):
        if v != v:  # NaN
            return ".nan"
        if v == float("inf"):
            return ".inf"
        if v == float("-inf"):
            return "-.inf"
        return json.dumps(v)
    if isinstance(v, (int,)):
        return str(v)
    raise TypeError("unexpected scalar type: %r" % type(v))


# ---------------------------------------------------------------------------
# Block-style emitter
# ---------------------------------------------------------------------------


def render_lines(v, indent=0):
    """Return a list of lines representing v as block-style YAML."""
    pad = INDENT * indent
    if isinstance(v, dict):
        if not v:
            return [pad + "{}"]
        out = []
        for k, val in v.items():
            key = quote_string(str(k))
            if isinstance(val, (dict, list)) and val:
                out.append("%s%s:" % (pad, key))
                out.extend(render_lines(val, indent + 1))
            elif isinstance(val, (dict, list)):
                out.append("%s%s: %s" % (pad, key, render_lines(val, 0)[0]))
            elif isinstance(val, str):
                out.append("%s%s: %s" % (pad, key, quote_string(val)))
            else:
                out.append("%s%s: %s" % (pad, key, render_scalar(val)))
        return out
    if isinstance(v, list):
        if not v:
            return [pad + "[]"]
        out = []
        for item in v:
            if isinstance(item, (dict, list)) and item:
                sub = render_lines(item, indent + 1)
                out.append("%s- %s" % (pad, sub[0].lstrip()))
                out.extend(sub[1:])
            elif isinstance(item, (dict, list)):
                out.append("%s- %s" % (pad, render_lines(item, 0)[0]))
            elif isinstance(item, str):
                out.append("%s- %s" % (pad, quote_string(item)))
            else:
                out.append("%s- %s" % (pad, render_scalar(item)))
        return out
    if isinstance(v, str):
        return [quote_string(v)]
    return [render_scalar(v)]


def dumps(data):
    return "\n".join(render_lines(data)) + "\n"


def main():
    try:
        data = json.load(sys.stdin)
    except json.JSONDecodeError as exc:
        sys.stderr.write("yamlout: invalid JSON input: %s\n" % exc)
        return 1
    sys.stdout.write(dumps(data))
    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
