import sys, random, string, yaml
sys.path.insert(0,'.')
import test_yamlout as t, yamlout

alphabet = string.printable + "café日本語\U0001F389"
fails = 0
for seed in range(20000):
    rng = random.Random(seed)
    doc = t.make_doc(rng)
    # extra nastiness: random strings incl. newlines/tabs as keys & values
    def mutate(v):
        if isinstance(v, dict): return {mutate(k) if False else k: mutate(val) for k,val in v.items()}
        if isinstance(v, list): return [mutate(i) for i in v]
        if isinstance(v, str) and rng.random() < 0.5:
            n = rng.randint(0,15)
            return "".join(rng.choice(alphabet) for _ in range(n))
        return v
    doc = {k: mutate(v) for k,v in doc.items()}
    text = yamlout.dumps(doc)
    try:
        loaded = yaml.safe_load(text)
        if loaded != doc:
            fails += 1
            print("MISMATCH seed", seed); 
            if fails > 3: break
    except Exception as e:
        fails += 1
        print("ERROR seed", seed, e); print(text[:400])
        if fails > 3: break
print("done, fails =", fails)
EOF')

